import re

with open('/tmp/decisions_yaml.txt', 'r') as f:
    lines = f.readlines()

# Check for any Cell A/Cell C mentions NOT in the already-found blocks
# The found decision blocks start at these lines (0-indexed):
found_starts = [1221, 1267, 1294, 1316, 1337, 1420, 1474, 1491, 1524, 1560, 1635, 1653, 1679, 1707, 1725, 1742, 1763, 1777, 1801, 1840, 1853, 1867, 1889, 1908, 1925, 1943, 1965, 2210]

# Find decision boundaries
decision_starts = []
for i, line in enumerate(lines):
    if re.match(r'^- id: D\d+', line):
        decision_starts.append(i)

# Cell A / Cell C pattern - but exclude Cell Agent, Cell Adapter etc.
cell_pattern = re.compile(r'Cell [AC](?!\w)')
matching = set()
for i, line in enumerate(lines):
    if cell_pattern.search(line):
        # find which decision block
        best = None
        for ds in decision_starts:
            if ds <= i:
                best = ds
            else:
                break
        if best is not None:
            matching.add(best)

not_found = matching - set(found_starts)
if not_found:
    print(f"Additional Cell A/C blocks not in ScienceWorld set: {sorted(not_found)}")
    for ds in sorted(not_found):
        end = len(lines)
        for next_ds in decision_starts:
            if next_ds > ds:
                end = next_ds
                break
        # Print the ID line
        print(f"  {lines[ds].strip()}")
else:
    print("All Cell A/C mentions are already captured in the extracted blocks.")
